.darma-loader-darma-b17-bandage-wrap { --accent: var(--loader-color, #e11d48); --accent-2: var(--loader-secondary-color, #fef2f2); width: var(--loader-size, 126px); height: calc(var(--loader-size, 126px) * .52); position: relative; }
.darma-loader-darma-b17-bandage-wrap .darma-loader-darma-b17-bandage-wrap__limb { position: absolute; left: 6%; right: 6%; top: 26%; height: 44%; border-radius: 999px; background: linear-gradient(color-mix(in srgb, #fff 25%, var(--accent)), var(--accent)); }
.darma-loader-darma-b17-bandage-wrap span { position: absolute; top: 20%; width: 13%; height: 56%; border-radius: 4px; background: var(--accent-2); box-shadow: inset -2px 0 0 color-mix(in srgb, #000 12%, transparent); transform-origin: 50% 50%; transform: scaleX(0) skewX(-14deg); animation: darma-loader-darma-b17-bandage-wrap-wrap-turn calc(var(--loader-speed, 1s) * 3) ease-in-out infinite; }
.darma-loader-darma-b17-bandage-wrap span:nth-of-type(1) { left: 10%; }
.darma-loader-darma-b17-bandage-wrap span:nth-of-type(2) { left: 24%; animation-delay: calc(var(--loader-speed, 1s) * .22); }
.darma-loader-darma-b17-bandage-wrap span:nth-of-type(3) { left: 38%; animation-delay: calc(var(--loader-speed, 1s) * .44); }
.darma-loader-darma-b17-bandage-wrap span:nth-of-type(4) { left: 52%; animation-delay: calc(var(--loader-speed, 1s) * .66); }
.darma-loader-darma-b17-bandage-wrap span:nth-of-type(5) { left: 66%; animation-delay: calc(var(--loader-speed, 1s) * .88); }
.darma-loader-darma-b17-bandage-wrap .darma-loader-darma-b17-bandage-wrap__roll { position: absolute; top: 20%; left: 76%; width: 22%; height: 42%; border-radius: 50%; background: radial-gradient(circle at 42% 36%, var(--accent-2), color-mix(in srgb, #000 14%, var(--accent-2))); box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 30%, transparent); animation: darma-loader-darma-b17-bandage-wrap-wrap-roll calc(var(--loader-speed, 1s) * 3) linear infinite; }
@keyframes darma-loader-darma-b17-bandage-wrap-wrap-turn { 0%, 6% { transform: scaleX(0) skewX(-14deg); opacity: 0; } 24%, 74% { transform: scaleX(1) skewX(-14deg); opacity: 1; } 92%, 100% { transform: scaleX(0) skewX(-14deg); opacity: 0; } }
@keyframes darma-loader-darma-b17-bandage-wrap-wrap-roll { to { transform: rotate(1turn); } }

